    "4672": "현재 편집자",
    "4676": "찾다...",
    "4684": "파일 이름, 설명, 태그 또는 확장명 검색...",
    "4685": "분석된 파일 이름, 기능, 태그 검색...",
    "4686": "디렉토리는 검사 순서대로 중첩됩니다.",
    "4693": "로컬 모델은 초등학교(내장), 중학교, 고등학교와 동일합니다. 클라우드 모델: 고등학교, 대학교",
    "4694": "로컬 AI 엔진",
    "4702": "모델은 다음 경로에 저장됩니다. 충분한 공간이 있는 고속 저장 디스크를 선택하는 것이 좋습니다.",
    "4714": "AI 엔진 파일 무결성 예외",
    "4715": "AI 파일이 불완전하여 제대로 작동하지 않을 수 있습니다.",
    "4716": "설치 과정에서 오류가 발생할 수 있고, 필요한 파일이 누락되어 AI 서비스가 다운되거나 저하될 수 있습니다.",
    "4717": "제안:",
    "4719": "설치 디렉터리에 쓰기 권한이 있는지 확인",
    "4720": "문제가 지속되면 앱을 제거했다가 다시 설치하세요.",
    "4721": "알고 있었다",
    "4740": "최소 단위 인식이 꺼졌습니다",
    "4741": "최소 단위 인식 활성화",
    "4742": "활성화되면 디렉터리가 가장 작은 단위로 식별되어 파일을 하나씩 건너뛰고 분석합니다.",
    "4744": "오디오 앨범: 동일한 앨범의 오디오 트랙 파일 모음(예: .flac, .mp3)",
    "4745": "시리즈 파일: 연속 번호가 붙은 문서 또는 사진(예: 01.jpg, 02.jpg, 03.jpg)",
    "4747": "팁: 닫은 후에는 모든 파일이 독립적으로 분석됩니다. 이는 각 파일에 대해 별도로 설명과 레이블을 생성해야 하는 시나리오에 적합합니다.",
