    "6227": "파일은 AI 분석을 거쳐야만 분류할 수 있으며, 너무 많으면 시간이 오래 걸릴 수 있습니다. 작업 모드에 따라 분석 결과를 서버에 캐시할지 여부가 결정됩니다.",
    "6229": "다운로드 디렉토리, 네트워크 리소스, 전자책, 만화, 음악 등 공개 파일입니다.",
    "6230": "분석 결과는 로컬에만 저장되며 서버에는 캐시되지 않아 데이터 주권을 보호합니다. 하지만 서버 캐시가 제공하는 속도 향상 효과는 누릴 수 없습니다.",
    "6231": "개인 창작 작품, 사진, 재무제표, 개인정보 문서 등입니다.",
