    "7681": "브라우저 창을 가져올 수 없습니다.",
    "7683": "AI 엔진 구성을 열려면 클릭하세요.",
    "7684": "클라우드 공유 원리 설명",
    "7685": "항상 개인정보 보호를 핵심 설계 원칙으로 간주하고 이를 준수합니다.",
    "7686": "데이터 로컬 우선순위",
    "7687": ", 사용자 개인 정보 보호 및 보안을 효과적으로 보호하기 위해 핵심 기술 원칙은 업계 공통 해시(Hash) 메커니즘과 논리적으로 일치합니다.",
    "7688": "간단히 말해서",
    "7689": ", 시스템은 암호화 알고리즘을 통해 각 파일에 대해 파일의 고유 ID와 동일한 고유 특성 식별자(길이 16-128자)를 생성합니다.",
    "7690": "이 ID를 생성하세요",
    "7691": "유일한 전제",
    "7692": ", 사용자는 파일을 로컬로 보유하고 알고리즘 계산을 완료합니다. 애플리케이션은 파일 ID를 제3자에게 공개하지 않습니다. 이 ID만이 해당 ID의 분석 데이터를 서버에 요청할 수 있으며, 이를 얻을 수 있는 다른 방법은 없습니다.",
    "7693": "심지어",
    "7694": "극단적인 가정하에",
    "7695": "(서버가 침해됨) 제3자는 파일 분석 데이터와 해당 ID만 얻을 수 있으며, 서로 다른 플랫폼의 ID 알고리즘은 완전히 독립적이며 Baidu Netdisk와 같은 플랫폼의 파일 ID와 연결되지 않으며 플랫폼 간에 원본 파일을 일치시킬 수 없습니다.",
    "7696": "동시에,",
    "7697": "서버는 분석 데이터만 저장합니다.",
    "7698": ": 스마트 파일 이름, 태그, 콘텐츠 요약, 평가 및 이유, 메타데이터 등을 포함하며, 이는 오른쪽 속성 패널에서 볼 수 있습니다. 파일 자체는 업로드되거나 저장되지 않습니다.",
