    "7826": "단일 텍스트 표시기(텍스트/문서/OCR/HTML)에 대한 최대 추출 크기, 너무 긴 내용은 자동으로 잘립니다. 그렇지 않으면 너무 많은 저장 공간을 차지하고 성능에 영향을 미칩니다.",
