    "7880": "더 빠른 모델 로딩과 더 원활한 AI 분석을 가능하게 하는 SSD(Solid State Drive)를 우선시합니다.",
    "7881": "빈 폴더를 선택하거나 새 폴더를 생성하면 기존 파일에는 영향을 미치지 않습니다.",
    "7883": "OCR 인식 정확도",
    "7884": "OCR 텍스트 인식의 정확도 수준을 선택합니다. 매우 빠른 OCR은 대부분의 시나리오에 적합합니다. 고정밀 OCR 인식은 더 정확하지만 시간이 조금 더 걸립니다.",
    "7885": "매우 빠른 OCR",
    "7887": "고정밀 OCR",
    "7889": "재분석 시 데이터 재사용",
    "7890": "파일이 업데이트된 경우 이 항목을 꺼주세요. 그렇지 않고, 어떤 파일의 기본 정보가 이미 존재하는 경우에는 이 정보 획득을 건너뜁니다. 기본 정보에는 파일 유형, 축소판, 메타데이터 및 파일 콘텐츠가 포함됩니다.",
    "7891": "분석 속도가 빨라지고 단순 분류 단계의 정보는 다시 획득되지 않습니다.",
