    "7905": "시스템 디렉터리, 소프트웨어 설치 디렉터리, 엔지니어링 프로젝트, 게임 패키지, AI 데이터 세트/모델, 캐시 및 LFS, 가상 환경 등의 범주는 강제로 식별되므로 활성화할 필요가 없습니다.",
    "7906": "디자인 프로젝트: 프로젝트 파일과 리소스 디렉터리(예: .prproj, .aep, .blend)가 포함된 디자인 프로젝트",
