    "9771": "대형 모델 서비스를 로컬에서 실행하기 위한 또 다른 외부 솔루션으로 Firefly의 내장 AI 엔진보다 20~40% 느리지만 하드웨어 호환성이 좋아 설치를 권장합니다.",
