    "9789": "SenseTime의 매우 빠른 추론 모델",
    "9792": "SenseTime에서 호스팅하는 DeepSeek 빠른 추론 모델",
    "9794": "가입하고 10달러 평가판을 받으세요. 신용카드는 필요하지 않습니다. 크레딧은 3개월 이내에 유효합니다. Jamba Large 및 Jamba Mini 모델이 포함됩니다.",
    "9795": "이스라엘",
    "9800": "Alibaba Cloud Bailian(국제 버전)",
    "9801": "등록 후 각 Tongyi Qianwen 모델은 90일 동안 유효한 100만 개의 무료 토큰을 받게 됩니다(국제/싱가포르 지역). 신용 카드가 필요하지 않습니다.",
    "9803": "무료 \"평가판\" API 키, 신용 카드가 필요하지 않습니다. 매월 1000개의 API 호출. 비상업적인 용도로만 사용하세요.",
    "9804": "캐나다",
    "9816": "무료 \"실험적\" 요금제이며 신용카드가 필요하지 않습니다. 매월 약 10억 개의 토큰. 모델을 개선하기 위해 큐 단어를 사용할 수 있습니다.",
    "9825": "지푸 AI",
    "9826": "영원히 무료 모델을 제공하며 신용 카드가 필요하지 않습니다.",
    "9829": "무료이며 신용 카드가 필요하지 않습니다. 매우 빠른 추론(약 2600개 토큰/초). 일일 한도는 100만 토큰입니다. 무료 파일 8K 컨텍스트 제한. llama3.1-8b는 2026년 5월 27일에 지원 중단될 예정입니다.",
    "9835": "매일 10,000개의 뉴런이 무료입니다. 무료 버전은 50개 이상의 모델을 제공합니다.",
    "9841": "모든 GitHub 사용자를 위한 무료 프로토타이핑 크레딧입니다. 45개 이상의 모델이 포함되어 있습니다. 단일 요청에는 제한이 있습니다(8K 입력/4K 출력).",
    "9846": "무료이며 신용 카드가 필요하지 않습니다. 매우 빠른 LPU 추론.",
    "9851": "무료 사용자에게 월간 추론 서비스 할당량 100,000회를 제공합니다. Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra 등과 같은 제공업체로 연결됩니다. 수천 개의 모델을 지원합니다.",
    "9855": "무료 모델이며 신용 카드가 필요하지 않습니다. `kilo-auto/free`는 자동으로 minimax/minimax-m2.5:free(80%) 및 stepfun/step-3.5-flash:free(20%)로 라우팅됩니다.",
    "9857": "원활한 API 게이트웨이. 기본 액세스에는 등록이 필요하지 않습니다. 30개 이상의 모델을 지원합니다. GDPR을 준수합니다.",
    "9858": "영국",
    "9862": "모델범위",
    "9863": "등록된 사용자에게 무료 API 추론 서비스를 제공합니다. Alibaba Cloud 계정을 바인딩하고 실명 인증을 완료해야 합니다.",
    "9868": "가입하고 $1의 무료 크레딧을 받으세요. 신용카드는 필요하지 않습니다. OpenAI 호환 API를 통해 60개 이상의 오픈 소스 모델을 사용할 수 있습니다. EU에 본사를 두고 있습니다.",
    "9869": "네덜란드",
    "9872": "가입하고 $5의 무료 크레딧을 받으세요. 신용카드는 필요하지 않습니다. 노르웨이에 데이터 센터를 둔 EU 주권 공급자입니다. 속도 제한도 없고 콜드 스타트도 없습니다.",
    "9874": "질적 사용 제한이 있는 무료입니다. Ollama 라이브러리에서 400개 이상의 모델을 제공합니다. OpenAI SDK와 호환되지 않으므로 [Ollama API](https://docs.ollama.com/cloud)를 사용하세요.",
    "9877": "OVHcloud AI 터미널",
    "9878": "무료 익명 프로필(API 키 없음, 등록 필요 없음): IP당 모델당 2RPM으로 제한됩니다. EU에서 40개 이상의 오픈 소스 체중 모델을 호스팅합니다. OpenAI SDK와 호환됩니다.",
    "9882": "무료 일일 토큰 할당량, 신용 카드가 필요하지 않습니다. 롤플레잉과 스토리 제작을 위해 설계되었습니다.",
    "9885": "분당 요청 수는 20개로 제한됩니다. 짧은 시간 내에 요청이 너무 빠르면 빈도 제한이 적용됩니다. (1분 정도 기다렸다가 다시 시도해야 함)",
    "9886": "싱가포르",
    "9889": "Sapiens AI의 빠르고 효율적인 모델은 이미지 이해를 지원합니다.",
    "9892": "단순 카테고리 전환",
    "9895": "Agnes AI 신규 클라우드 서비스 제공, 영구 무료 API, 중국 내 네트워크에서 정상적으로 접속 가능",
    "9897": "일괄 정렬({count})",
