    "11449": "키워드로 디렉토리 간 검색",
    "11450": "나는 지저분한 데스크탑,다운로드 카탈로그 등을 구성하는 사용하기 쉬운 오픈 소스 무료 인공 지능 도구\"반딧불 코어 스마트 폴더\"를 발견했습니다. 한 번의 클릭으로,인공 지능이 자동으로 분류/이름 변경/태그/설명/썸네일 이미지/아카이브/청소!로컬 인공 지능 기능을 사용하여 개인 정보를 보호하고 가상 디렉토리 정렬 기술을 혁신하여 파일 보안을 보장하십시오! 초대 코드를 사용하여 더 많은 고급 혜택을 잠금 해제하십시오",
    "11451": "개인 디렉토리의 무제한 할당량 잠금 해제",
