    "11457": "파일을 삭제하면 시스템 휴지통으로 안전하게 이동되며, 언제든지 복원할 수 있습니다",
    "11458": "휴지통 안전 보호, 언제든지 복원 지원",
    "11459": "휴지통 안전 보호",
    "11460": "FireFly Omni의 지능형 분석을 기반으로 불필요한 파일을 안전하게 정리하며, 모든 삭제된 파일은 시스템 휴지통으로 이동되어 언제든지 복원할 수 있습니다.",
    "11461": "형식 요구사항 복사",
