    "11508": "영구적으로 유효함",
    "11509": "금액은 원래 결제 수단으로 환불되었으며, 상품의 혜택은 종료되었습니다.",
    "11510": "권리는 완전히 보존되어 있으며, 집행 계획의 만료 시점이 지나면 그 시점부터 기산됩니다.",
