    "11520": "사용자 지정 청구서 및 자동 갱신 서비스 (고객 포털)",
    "11521": "Creem 국제 고객 포털을 통해 언제든지 과거 청구서 및 영수증을 다운로드하거나, 결제용 신용카드를 업데이트하거나, 다음 기간의 자동 갱신을 해지할 수 있습니다. 자동 갱신을 해지하더라도 현재 청구 주기 내의 모든 회원 혜택에는 영향을 미치지 않습니다.",
    "11522": "국제 결제 포털로 이동하여 청구서 관리 및 갱신하기",
