    "11526": "정기적인 라이선스 보장",
    "11527": "현재 권한은 카드 미연동 고정 주기 방식으로 설정되어 있으며, 어떠한 자동 결제나 출금 위험도 전혀 없습니다. 권한 만료 후 시스템은 무료로 원활하게 전환되며, 추가 요금이 발생하지 않습니다. 기간 연장을 원하시면 고객센터로 문의해 주십시오.",
