    "11535": "공식 웹사이트에서 Pro 버전으로 업그레이드하기",
    "11536": "공식 웹사이트의 가격 정책 센터에서 Pro 버전을 구매하시면, 시스템이 해당 식별 코드를 기반으로 현재 기기에 자동으로 연동하여 즉시 활성화됩니다.",
    "11537": "기기 식별 코드가 클립보드에 복사되었습니다.",
